"""Claims resolve against evidence files at render time. This is the only place a number can enter a video."""

from __future__ import annotations

import hashlib
import importlib.util
import json
from pathlib import Path
from typing import Any

from .spec import Claim, Spec

ROOT = Path(__file__).resolve().parents[3]
EV = ROOT / "evidence"


def _file(ref: str) -> Path:
    kind, _, rest = ref.partition(":")
    name = rest.split("#", 1)[0]
    if kind == "report":
        files = sorted((EV / "reports").glob(f"*-{name}.json"))  # the latest report of that sweep
        if not files:
            raise FileNotFoundError(f"no report for sweep '{name}'")
        return files[-1]
    if kind == "file":
        p = (ROOT / name).resolve()
        if ROOT not in p.parents or "_private" in p.parts:
            raise ValueError(f"claim file outside the repo or private: {name}")
        return p
    raise ValueError(f"unknown claim source '{ref}'")


def _dig(obj: Any, path: str) -> Any:
    for part in path.split("."):
        obj = obj[int(part)] if isinstance(obj, list) else obj[part]
    return obj


def _num(x: Any) -> Any:
    return x if isinstance(x, (int, float)) else float(x)


def resolve_claim(c: Claim) -> dict:
    sources, values = [], []
    for ref in c.refs:
        f = _file(ref)
        v = _num(_dig(json.loads(f.read_text(encoding="utf-8")), ref.split("#", 1)[1]))
        values.append(v)
        sources.append({"ref": ref, "file": str(f.relative_to(ROOT)).replace("\\", "/"), "value": v,
                        "sha256": hashlib.sha256(f.read_bytes()).hexdigest()[:16]})  # fmt: skip
    return {
        "id": c.id, "label": c.label, "display": c.fmt.format(*values),
        "spoken": (c.spoken or c.fmt).format(*values),
        "ratio": (values[0] / values[1]) if c.ratio and values[1] else None,
        "sources": sources,
    }  # fmt: skip


def resolve(spec: Spec) -> dict[str, dict]:
    return {c.id: resolve_claim(c) for c in spec.claims}


def _report_module():
    p = ROOT / "scripts" / "report.py"
    s = importlib.util.spec_from_file_location("storybound_report_script", p)
    m = importlib.util.module_from_spec(s)
    s.loader.exec_module(m)  # type: ignore[union-attr]
    return m


def recompute_from_ledger(ref: str) -> Any:
    """For a `report:` ref, rebuild the number from the raw ledger rows, independent of the saved report file."""
    rep = _report_module()
    name, path = ref.split(":", 1)[1].split("#", 1)
    return _dig(rep.summarise(rep.rows_for(name)), path)

"""Spec + resolved claims + narration audio -> a HyperFrames project (one index.html, seeked GSAP timeline)."""

from __future__ import annotations

import html
import json
import shutil
from pathlib import Path

from .claims import ROOT
from .spec import Spec

HARNESS = ROOT / "video" / "harness"
TAIL_S = 1.0
LEAD_S = 0.4

CSS = """
*{margin:0;padding:0;box-sizing:border-box}
html,body{width:1920px;height:1080px;overflow:hidden;background:#fff7e6}
#root{width:1920px;height:1080px;position:relative;font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#2b2140}
.scene{position:absolute;left:0;top:0;width:1920px;height:1080px;padding:150px 140px 110px;display:flex;
  flex-direction:column;gap:38px;background:#fff7e6}
.brand{position:absolute;left:140px;top:56px;font-size:34px;font-weight:800;color:#7a4fd0;letter-spacing:-.01em}
.foot{position:absolute;left:140px;bottom:44px;font-size:24px;color:#6b6280}
h1{font-size:112px;font-weight:800;line-height:1.04;letter-spacing:-.03em}
p.t{font-size:56px;font-weight:500;line-height:1.25;max-width:1500px}
.claim{display:flex;flex-direction:column;gap:6px}
.claim .num{font-size:230px;font-weight:800;line-height:1;color:#2a7f62}
.claim .lab{font-size:50px;font-weight:600}
.src{font-size:24px;color:#6b6280;font-weight:500}
.row{display:flex;align-items:center;gap:34px}
.rl{width:430px;font-size:46px;font-weight:700}
.track{width:1000px;height:70px;background:#eadfc7;border-radius:16px;overflow:hidden}
.fill{height:70px;min-width:8px;border-radius:16px}
.rv{font-size:56px;font-weight:800;width:250px}
.good{background:#2a7f62;color:#2a7f62}.bad{background:#c0504d;color:#c0504d}
.rv.good,.rv.bad{background:none}
ul{list-style:none;display:flex;flex-direction:column;gap:26px}
li{font-size:56px;font-weight:600;display:flex;align-items:center;gap:28px}
li:before{content:"";width:26px;height:26px;border-radius:50%;background:#7a4fd0;flex:none}
img.pic{max-height:560px;border-radius:24px;align-self:flex-start}
"""


def _spoken(narration: str, resolved: dict[str, dict]) -> str:
    out = narration
    for cid, r in resolved.items():
        out = out.replace("{" + cid + "}", r["spoken"])
    return out


def spoken_text(spec: Spec, resolved: dict[str, dict]) -> dict[str, str]:
    return {s.id: _spoken(s.narration, resolved) for s in spec.scenes}


def _sources(cids: list[str], resolved: dict[str, dict]) -> str:
    seen: list[str] = []
    for cid in cids:
        for s in resolved[cid]["sources"]:
            tag = f"{Path(s['file']).name} · {s['ref'].split('#', 1)[1]}"
            if tag not in seen:
                seen.append(tag)
    return html.escape("source: " + "; ".join(seen))


def build(spec: Spec, resolved: dict[str, dict], audio: dict[str, tuple[Path, float]], out: Path) -> dict:
    """Write the project into `out`. `audio[scene id] = (mp3 path, seconds)`. Returns the timeline."""
    out.mkdir(parents=True, exist_ok=True)
    for f in ("hyperframes.json", "package.json"):
        shutil.copy(HARNESS / "template" / f, out / f)
    (out / "meta.json").write_text(json.dumps({"id": spec.title, "name": spec.title}), encoding="utf-8")
    (out / "vendor").mkdir(exist_ok=True)
    shutil.copy(HARNESS / "vendor" / "gsap.min.js", out / "vendor" / "gsap.min.js")
    (out / "audio").mkdir(exist_ok=True)

    t, scenes, parts, audio_tags, js = 0.0, [], [], [], []
    for i, sc in enumerate(spec.scenes):
        mp3, vo = audio[sc.id]
        dur = max(sc.min_seconds, vo + LEAD_S + 0.8)
        scenes.append({"id": sc.id, "start": round(t, 3), "dur": round(dur, 3), "vo": round(vo, 3)})
        shutil.copy(mp3, out / "audio" / f"vo-{i}.mp3")
        audio_tags.append(
            f'<audio id="vo-{i}" data-start="{t + LEAD_S:.3f}" data-duration="{vo:.3f}" '
            f'data-track-index="{10 + i}" src="audio/vo-{i}.mp3" data-volume="1"></audio>'
        )
        body = [f'<div class="brand" id="s{i}-brand">Storybound</div>']
        js.append(f'tl.from("#s{i}-brand",{{opacity:0,duration:.4}},{t:.3f});')
        for j, b in enumerate(sc.blocks):
            bid, at = f"s{i}b{j}", t + LEAD_S + 0.35 * j
            if b.type == "title":
                body.append(f'<h1 id="{bid}">{html.escape(b.text)}</h1>')
            elif b.type == "text":
                body.append(f'<p class="t" id="{bid}">{html.escape(b.text)}</p>')
            elif b.type == "claim":
                r = resolved[b.claim]
                body.append(
                    f'<div class="claim" id="{bid}"><div class="num">{html.escape(r["display"])}</div>'
                    f'<div class="lab">{html.escape(r["label"])}</div>'
                    f'<div class="src">{_sources([b.claim], resolved)}</div></div>'
                )
            elif b.type == "bars":
                rows, cids = [], []
                for k, it in enumerate(b.items):
                    r = resolved[it["claim"]]
                    cids.append(it["claim"])
                    tone = it.get("tone", "good")
                    pct = round(100 * (r["ratio"] or 0), 1)
                    rows.append(
                        f'<div class="row" id="{bid}r{k}"><div class="rl">{html.escape(it["label"])}</div>'
                        f'<div class="track"><div class="fill {tone}" id="{bid}f{k}" style="width:{pct}%"></div></div>'
                        f'<div class="rv {tone}">{html.escape(r["display"])}</div></div>'
                    )
                    js.append(
                        f'tl.from("#{bid}f{k}",{{width:"0%",duration:1.1,ease:"power2.out"}},{at + 0.3 + 0.25 * k:.3f});'
                    )
                body.append(f'<div id="{bid}" style="display:flex;flex-direction:column;gap:30px">{"".join(rows)}'
                            f'<div class="src">{_sources(cids, resolved)}</div></div>')  # fmt: skip
            elif b.type == "list":
                lis = "".join(f"<li>{html.escape(str(x))}</li>" for x in b.items)
                body.append(f'<ul id="{bid}">{lis}</ul>')
            elif b.type == "image":
                src = Path(b.src)
                shutil.copy(ROOT / src, out / "audio" / src.name)  # same folder keeps the project flat
                body.append(f'<img class="pic" id="{bid}" src="audio/{src.name}"/>')
            js.append(f'tl.from("#{bid}",{{opacity:0,y:44,duration:.6,ease:"power2.out"}},{at:.3f});')
        body.append(f'<div class="foot" id="s{i}-foot">#neatHack · every number on screen is read from an evidence file</div>')
        parts.append(
            f'<section id="scene-{i}" class="clip scene" data-start="{t:.3f}" data-duration="{dur:.3f}" '
            f'data-track-index="1">{"".join(body)}</section>'
        )  # fmt: skip
        t += dur
    total = round(t + TAIL_S, 3)
    doc = (
        '<!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=1920, height=1080"/>'
        f'<script src="vendor/gsap.min.js"></script><style>{CSS}</style></head><body>'
        f'<div id="root" data-composition-id="main" data-start="0" data-duration="{total}" data-width="1920" data-height="1080">'
        f'{"".join(parts)}{"".join(audio_tags)}</div>'
        f'<script>const tl=gsap.timeline({{paused:true}});{"".join(js)}window.__timelines["main"]=tl;tl.seek(0);</script></body></html>'
    )
    (out / "index.html").write_text(doc, encoding="utf-8")
    return {"scenes": scenes, "total": total}

"""The video oath: deterministic promises checked before a video ships. Same verdict shape as the story oath."""

from __future__ import annotations

import json
import re
import shutil
import subprocess
from pathlib import Path

from .claims import ROOT, recompute_from_ledger
from .spec import Spec

TOOLS = ("neatlogs", "entire", "cfo.ai")
POINTS = ("architecture", "implementation", "runtime", "reasoning", "result")
KEY_LIKE = re.compile(r"(AKIA[0-9A-Z]{16}|ya29\.[0-9A-Za-z_-]{20,}|sk-[A-Za-z0-9]{20,}|IFM-[A-Za-z0-9]{12,}|[A-Za-z0-9]{32,})")
LUFS_RANGE = (-19.0, -13.0)


def _v(commitment: str, ok: bool, expected: str, actual: str, scene: str | None = None) -> dict:
    return {"commitment": commitment, "status": "pass" if ok else "violation", "expected": expected,
            "actual": actual, "scene": scene}  # fmt: skip


def _texts(spec: Spec):
    """Every string that reaches the screen or the narration, except resolved claim values."""
    for s in spec.scenes:
        yield s.id, "narration", s.narration
        for b in s.blocks:
            if b.text:
                yield s.id, f"{b.type} text", b.text
            for it in b.items:
                if isinstance(it, str):
                    yield s.id, "list item", it
                else:
                    yield s.id, "bar label", it.get("label", "")
    for c in spec.claims:
        yield "claims", f"claim label {c.id}", c.label


def length_ok(spec: Spec, total: float) -> dict:
    return _v("length_ok", total <= spec.max_seconds, f"at most {spec.max_seconds:.0f} s", f"{total:.1f} s")


def claims_sourced(spec: Spec) -> list[dict]:
    """No digit may appear outside a claim: numbers come from evidence files, never from the writer."""
    bad = [(sid, where, t) for sid, where, t in _texts(spec) if re.search(r"\d", re.sub(r"\{[\w.-]+\}", "", t))]
    if not bad:
        return [_v("claims_sourced", True, "no typed numbers", "none found")]
    return [_v("claims_sourced", False, "no typed numbers; use a claim", f"digit in {where}: '{t[:60]}'", sid) for sid, where, t in bad]


def claims_match_ledger(resolved: dict[str, dict]) -> list[dict]:
    """Rebuild every report-backed number from the raw ledger and compare with what the video shows."""
    out = []
    for cid, r in resolved.items():
        for s in r["sources"]:
            if not s["ref"].startswith("report:"):
                continue
            try:
                again = recompute_from_ledger(s["ref"])
                ok = abs(float(again) - float(s["value"])) < 1e-9
                out.append(_v("claims_match_ledger", ok, f"{s['value']} (report file)", f"{again} (ledger rebuild)", cid))
            except Exception as e:  # the ledger changed shape, a missing path: cannot be verified
                out.append({**_v("claims_match_ledger", False, "rebuild from ledger", f"{type(e).__name__}: {e}", cid), "status": "verification_error"})
    return out or [_v("claims_match_ledger", True, "report-backed claims", "none to check")]


def tools_covered(spec: Spec) -> dict:
    if not spec.requires_coverage:
        return _v("tools_covered", True, "not required for this video", "skipped")
    have = {c for s in spec.scenes for c in s.covers}
    missing = [f"{t}:{p}" for t in TOOLS for p in POINTS if f"{t}:{p}" not in have]
    return _v("tools_covered", not missing, "each tool on all five points", "missing: " + ", ".join(missing) if missing else "all 15 covered")


def _env_secrets() -> list[str]:
    f = ROOT / ".env"
    vals = []
    if f.exists():
        for ln in f.read_text(encoding="utf-8").splitlines():
            if "=" in ln and not ln.lstrip().startswith("#"):
                k, v = ln.split("=", 1)
                v = v.strip().strip("'\"")
                if re.search(r"KEY|SECRET|TOKEN|PASSWORD", k, re.I) and len(v) >= 12:
                    vals.append(v)
    return vals


def no_secrets(spec: Spec, resolved: dict[str, dict]) -> dict:
    blob = json.dumps(spec.model_dump()) + json.dumps(resolved)
    hit = KEY_LIKE.search(re.sub(r"[a-f0-9]{16}", "", blob))  # source hashes are 16 hex characters, not keys
    leaked = any(v in blob for v in _env_secrets())
    return _v("no_secrets", not hit and not leaked, "no key-like strings, no .env values", "found one" if (hit or leaked) else "none found")


def no_child_data(spec: Spec) -> dict:
    bad = [b.src for s in spec.scenes for b in s.blocks if b.type == "image" and (not b.src.startswith("assets/") or "_private" in b.src)]
    return _v("no_child_data", not bad, "images only from assets/ (fixtures and brand art)", f"outside the allow-list: {bad}" if bad else "all images allowed")


def static(spec: Spec, resolved: dict[str, dict], total: float) -> list[dict]:
    return [length_ok(spec, total), *claims_sourced(spec), *claims_match_ledger(resolved), tools_covered(spec),
            no_secrets(spec, resolved), no_child_data(spec)]  # fmt: skip


def loudness(mp4: Path) -> float | None:
    ff = shutil.which("ffmpeg") or "ffmpeg"
    p = subprocess.run([ff, "-nostats", "-i", str(mp4), "-af", "ebur128=peak=true", "-f", "null", "-"],
                       capture_output=True, text=True, encoding="utf-8", errors="replace")  # fmt: skip
    m = re.findall(r"I:\s+(-?\d+\.\d+) LUFS", p.stderr)
    return float(m[-1]) if m else None


def audio_ok(mp4: Path, timeline: dict) -> dict:
    lufs = loudness(mp4)
    if lufs is None:
        return {**_v("audio_ok", False, "measurable loudness", "could not measure"), "status": "verification_error"}
    lo, hi = LUFS_RANGE
    return _v("audio_ok", lo <= lufs <= hi, f"{lo} to {hi} LUFS", f"{lufs} LUFS")


def renders_clean(chk: dict) -> dict:
    return _v("renders_clean", chk["passed"], "HyperFrames check passes (lint, runtime, layout, motion, contrast)",
              "passed" if chk["passed"] else "; ".join(chk["problems"])[:400] or "check failed")  # fmt: skip

